import { useMemo, useState } from 'react';
import {
  Badge,
  Pagination,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
} from '@jinx-ui/react';

// Имена компонентов Jinx UI взяты по предположению — сверь с версией пакета в проекте.

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string | number;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
  pageSize?: number;
}

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_TONE: Record<UserStatus, 'success' | 'neutral'> = {
  active: 'success',
  disabled: 'neutral',
};

function UsersTable({ users, pageSize = 10 }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / pageSize));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * pageSize, currentPage * pageSize),
    [users, currentPage, pageSize],
  );

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
      <Table className="jx-table">
        <TableHead>
          <TableRow>
            <TableCell as="th">Имя</TableCell>
            <TableCell as="th">Роль</TableCell>
            <TableCell as="th">Статус</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {rows.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                <Badge tone={STATUS_TONE[user.status]}>
                  {STATUS_LABEL[user.status]}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      <Pagination
        page={currentPage}
        pageCount={pageCount}
        onPageChange={setPage}
      />
    </Stack>
  );
}

export default UsersTable;

